def backfill_order_totals(apps, schema_editor):
    Order = apps.get_model('api', 'OrdenExportacion')
    OrderLot = apps.get_model('api', 'OrdenLote')
    for order in Order.objects.all().iterator():
        rate = order.tasa_cambio_cop or Decimal('4200.00')
        total_eur = order.valor_total_eur or Decimal('0.00')
        Order.objects.filter(pk=order.pk).update(
            valor_total_cop=(total_eur * rate).quantize(Decimal('0.01'))
        )
        for line in OrderLot.objects.filter(orden_id=order.pk).select_related('lote'):
            product = getattr(line.lote, 'producto', None)
            if product:
                price = product.precio_unitario_eur
            else:
                price = (
                    Decimal('8.50')
                    if line.lote.tipo_producto == 'Café'
                    else Decimal('6.80')
                )
            subtotal = (line.cantidad_kg * price).quantize(Decimal('0.01'))
            OrderLot.objects.filter(pk=line.pk).update(
                precio_unitario_eur=price,
                subtotal_eur=subtotal,
            )


